def update_user_role(user_id, new_role, current_user_role):
    roles = ['guest', 'member', 'admin']
    if current_user_role not in roles or new_role not in roles:
        raise ValueError('Invalid role provided')
    if current_user_role != 'admin':
        raise PermissionError('Only admin can update roles')
    if user_id < 1000 or user_id > 1005:
        raise ValueError('Invalid user ID')
    return f'User {user_id} role updated to {new_role}."
